import { Activity, Boxes, Eye, ShoppingCart } from 'lucide-react';

import { AdminMetric, AdminPage, AdminPageHeader, AdminPanel } from '@/features/admin/components';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { prisma } from '@/lib/prisma';

export default async function VendorAnalyticsPage(){const access=await getVendorAccess();if(!access.permissions.has('analytics:view'))throw new Error('Analytics access is required.');const since=new Date();since.setDate(since.getDate()-30);const productIds=(await prisma.product.findMany({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id},select:{id:true}})).map(item=>item.id);const campaignIds=(await prisma.storeStudioCampaign.findMany({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id},select:{id:true}})).map(item=>item.id);const [events,topProducts]=await Promise.all([prisma.experienceEvent.groupBy({by:['type'],where:{workspaceId:access.workspace.id,createdAt:{gte:since},OR:[{productId:{in:productIds}},{campaignId:{in:campaignIds}}]},_count:{_all:true},orderBy:{_count:{type:'desc'}}}),prisma.experienceEvent.groupBy({by:['productId'],where:{workspaceId:access.workspace.id,createdAt:{gte:since},productId:{in:productIds}},_count:{_all:true},orderBy:{_count:{productId:'desc'}},take:8})]);const names=await prisma.product.findMany({where:{id:{in:topProducts.map(item=>item.productId).filter((value):value is string=>Boolean(value))}},select:{id:true,name:true}});const byId=new Map(names.map(item=>[item.id,item.name]));const eventMap=new Map(events.map(item=>[item.type,item._count._all]));const total=events.reduce((sum,item)=>sum+item._count._all,0);const views=(eventMap.get('PRODUCT_VIEW')??0)+(eventMap.get('CAMPAIGN_VIEW')??0);const cart=eventMap.get('ADD_TO_CART')??0;const max=Math.max(...events.map(item=>item._count._all),1);return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Last 30 days" title="Vendor Analytics" description="Activity is isolated to your products and Store Studio campaigns."/><section className="grid gap-3 sm:grid-cols-3"><AdminMetric icon={Activity} label="Tracked events" value={total}/><AdminMetric icon={Eye} label="Views" value={views}/><AdminMetric icon={ShoppingCart} label="Add to cart" value={cart}/></section><section className="grid gap-5 xl:grid-cols-2"><AdminPanel title="Activity distribution"><div className="space-y-3">{events.map(item=><div key={item.type}><div className="flex justify-between text-[10px]"><span className="font-bold">{item.type.replaceAll('_',' ')}</span><span>{item._count._all}</span></div><div className="mt-1 h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:`${Math.max(item._count._all/max*100,2)}%`}}/></div></div>)}</div></AdminPanel><AdminPanel title="Top products"><div className="space-y-3">{topProducts.map((item,index)=><div key={item.productId??index} className="flex items-center gap-3 rounded-2xl border border-border/60 p-3"><span className="grid size-8 place-items-center rounded-xl bg-primary/10 text-[10px] font-black text-primary">{index+1}</span><Boxes className="size-4 text-muted-foreground"/><p className="min-w-0 flex-1 truncate text-xs font-bold">{item.productId?byId.get(item.productId)??'Unknown product':'Unknown product'}</p><span className="text-xs font-black">{item._count._all}</span></div>)}</div></AdminPanel></section></div></AdminPage>}
